script:
frappe.ui.form.on("Journal Entry", {
    refresh(frm) {
        if (frm.is_new()) {
            frm.set_value("is_system_generated", 0);
        }
    },

    onload(frm) {
        if (frm.is_new()) {
            frm.set_value("is_system_generated", 0);
        }
    }
});

frappe.ui.form.on('Leave Application', {
    before_workflow_action(frm) {
        if (frm.selected_workflow_action === 'Approve') {
            frm.doc.custom_rejection_reason = 'N/A';
            return;
        }

        if (frm.selected_workflow_action === 'Reject') {
            if (!frm.doc.custom_rejection_reason || 
                frm.doc.custom_rejection_reason.trim() === '' || 
                frm.doc.custom_rejection_reason.trim() === 'N/A') {

                frappe.msgprint({
                    title: 'Rejection Reason Required',
                    message: 'Please fill in the <b>Rejection Reason</b> before rejecting.',
                    indicator: 'red'
                });

                frappe.dom.unfreeze();
                frm.scroll_to_field('custom_rejection_reason');
                return Promise.reject();
            }
        }
    }
});

frappe.ui.form.on('Subcontracting Receipt', {
    refresh(frm) {
        calculate_service_cost_tax(frm);
    },

    validate(frm) {
        calculate_service_cost_tax(frm);
    },

    before_save(frm) {
        calculate_service_cost_tax(frm);
    }
});

frappe.ui.form.on('Subcontracting Receipt Item', {
    service_cost_per_qty(frm) {
        calculate_service_cost_tax(frm);
    },

    qty(frm) {
        calculate_service_cost_tax(frm);
    },

    items_remove(frm) {
        calculate_service_cost_tax(frm);
    }
});

function calculate_service_cost_tax(frm) {
    const items = frm.doc.items || [];
    const taxes = frm.doc.taxes || [];

    let total_service_cost = 0;

    items.forEach(item => {
        total_service_cost +=
            flt(item.service_cost_per_qty) * flt(item.qty);
    });

    frm.doc.custom_total_service_cost = total_service_cost;

    let total_taxes = 0;
    let running_total = total_service_cost;

    taxes.forEach(tax => {
        let tax_amount = 0;

        if (tax.charge_type === 'On Net Total') {

            let tax_rate = get_tax_rate(tax, items);

            tax_amount =
                total_service_cost * tax_rate / 100;

            running_total += tax_amount;

        } else if (tax.charge_type === 'On Previous Row Total') {

            let tax_rate = flt(tax.rate);

            tax_amount =
                running_total * tax_rate / 100;

            running_total += tax_amount;
        }

        tax.tax_amount = tax_amount;
        tax.base_total = running_total;

        total_taxes += tax_amount;
    });

    frm.doc.total_taxes = total_taxes;
    frm.doc.base_grand_total =
        total_service_cost + total_taxes;

    frm.refresh_field('custom_total_service_cost');
    frm.refresh_field('taxes');
    frm.refresh_field('total_taxes');
    frm.refresh_field('base_grand_total');
}


function get_tax_rate(tax, items) {

    if (flt(tax.rate)) {
        return flt(tax.rate);
    }

    let rate = 0;

    items.forEach(item => {

        if (tax.gst_tax_type === 'igst') {
            rate = Math.max(
                rate,
                flt(item.igst_rate)
            );
        }

        else if (tax.gst_tax_type === 'cgst') {
            rate = Math.max(
                rate,
                flt(item.cgst_rate)
            );
        }

        else if (tax.gst_tax_type === 'sgst') {
            rate = Math.max(
                rate,
                flt(item.sgst_rate)
            );
        }

        else if (tax.gst_tax_type === 'cess') {
            rate = Math.max(
                rate,
                flt(item.cess_rate)
            );
        }

    });

    return rate;
}
